import {projects,members,statuses,priorities,getStats,filterTasks,offsetDate} from './model.mjs';

export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
 logo:'M4 7h10a4 4 0 0 1 0 8H8a4 4 0 0 1 0-8m0 8h12',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 board:'M4 4h16v16H4zM9 4v16m6-16v16',
 list:'M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1',
 search:'m16 16 5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
 sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',
 moon:'M21 13a9 9 0 0 1-10-10 9 9 0 1 0 10 10Z',
 plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',chevron:'m8 10 4 4 4-4',arrow:'M4 12h16m-6-6 6 6-6 6',arrowup:'M7 17 17 7M7 7h10v10',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
 calendar:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2ZM7 2v4m10-4v4M3 10h18',
 clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 flag:'M5 21V3m0 1c5-4 9 4 14 0v9c-5 4-9-4-14 0',
 checkcircle:'m7 12 3 3 7-7M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
 circle:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
 settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 2h6l1 4 4 1 2 5-3 3v5l-5 2-3-3H6l-3-5 3-3V6z',
 reset:'M3 10a9 9 0 1 1 1 8M3 4v6h6',
 link:'m10 13 4-4m-6 7-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
 folder:'M3 7V4h6l3 3h9v13H3z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',
 chat:'M21 11a9 9 0 0 1-9 9H3l2-4a9 9 0 1 1 16-5Z',
 clip:'m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3',
 close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',more:'M5 12h.01M12 12h.01M19 12h.01',
 trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',
 bolt:'m13 2-9 12h7l-1 8 10-13h-7z',target:'M20 12a8 8 0 1 1-8-8m0 8 9-9m-4 0h4v4M15 12a3 3 0 1 1-3-3',
 help:'M9 9a3 3 0 1 1 4 3v3m-1 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'
};
export const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.circle}"/></svg>`;
export const logo=()=>`<span class="logo-mark">${icon('logo')}</span><span class="logo-text">flow<span>.</span></span>`;
export const themeButton=()=>`<button class="icon-button theme-toggle" data-action="theme" aria-label="Chuyển giao diện" aria-pressed="false" title="Chuyển giao diện">${icon('moon')}</button>`;
export const avatar=(id,size='')=>{const m=members.find(x=>x.id===id)||members[0];return `<span class="avatar ${m.color} ${size}" title="${m.name}" aria-label="${m.name}">${m.initial}</span>`;};
export const avatarGroup=()=>`<div class="avatar-group">${members.slice(0,3).map(m=>avatar(m.id,'small')).join('')}<span class="avatar avatar-more small" title="4 thành viên mẫu">+1</span></div>`;
export const priority=(p)=>`<span class="priority ${esc(p)}">${icon('flag')}${priorities[p]}</span>`;
export const projectChip=(id)=>{const p=projects.find(x=>x.id===id)||projects[0];return `<span class="project-chip"><i class="dot ${p.color}"></i>${p.name}</span>`;};
export const formatDate=(date)=>{if(!date)return 'Chưa đặt hạn';return new Intl.DateTimeFormat('vi-VN',{day:'2-digit',month:'2-digit'}).format(new Date(date+'T12:00:00'));};
export const dueLabel=(t,today)=>t.due===today?'Hôm nay':t.due===offsetDate(today,1)?'Ngày mai':formatDate(t.due);
export function emptyState(title='Không tìm thấy công việc',text='Thử thay đổi bộ lọc hoặc tạo một công việc mới.'){return `<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${text}</p><button class="button secondary" data-action="clear-filters">Xóa bộ lọc</button></div>`;}

export function shell(content,route,state,today,filters){
 const names={app:'Tổng quan',board:'Bảng công việc',tasks:'Danh sách công việc'};
 const currentProject=projects.find(p=>p.id===filters.project);
 return `<div class="workspace"><aside class="sidebar" id="sidebar"><a href="#/" class="brand" aria-label="Flow — Trang giới thiệu">${logo()}</a><button class="workspace-switch" data-action="workspace-info"><span class="workspace-symbol">S</span><span>Studio Workspace<small>Không gian cá nhân</small></span>${icon('chevron')}</button><div class="sidebar-label">KHÔNG GIAN LÀM VIỆC</div><nav aria-label="Điều hướng ứng dụng"><a href="#/app" class="nav-link ${route==='app'?'active':''}" ${route==='app'?'aria-current="page"':''}>${icon('grid')}<span>Tổng quan</span></a><a href="#/board" class="nav-link ${route==='board'?'active':''}" ${route==='board'?'aria-current="page"':''}>${icon('board')}<span>Bảng công việc</span><span class="nav-count">${state.tasks.filter(t=>t.status!=='done').length}</span></a><a href="#/tasks" class="nav-link ${route==='tasks'?'active':''}" ${route==='tasks'?'aria-current="page"':''}>${icon('list')}<span>Tất cả công việc</span></a></nav><div class="sidebar-label projects-label">DỰ ÁN CỦA BẠN <span>${projects.length}</span></div><nav aria-label="Dự án">${projects.map(p=>`<a class="nav-link project-nav ${filters.project===p.id?'selected':''}" href="#/board?project=${p.id}"><span class="project-square ${p.color}">${p.initial}</span><span>${p.name}</span></a>`).join('')}</nav><div class="sidebar-spacer"></div><div class="sidebar-tip"><span class="tip-icon">${icon('spark')}</span><h4>Ít bận rộn. Nhiều tiến độ.</h4><p>Mỗi việc hoàn thành là một bước gần hơn đến mục tiêu.</p><button data-action="new-task">Tạo công việc đầu tiên ${icon('arrowup')}</button></div><div class="sidebar-bottom"><button data-action="about" class="nav-link">${icon('help')}<span>Về bản demo</span><span class="demo-pill">DEMO</span></button><button data-action="reset" class="nav-link">${icon('reset')}<span>Khôi phục dữ liệu mẫu</span></button><div class="profile">${avatar('an')}<span><strong>Minh An</strong><small>Freelancer · Tài khoản mẫu</small></span><span class="online-dot"></span></div></div></aside><div class="sidebar-scrim" data-action="close-menu"></div><div class="workspace-main"><header class="app-topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Mở điều hướng" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb"><span>Không gian làm việc</span><span>/</span><strong>${currentProject?currentProject.name:names[route]}</strong></div><div class="topbar-tools"><form class="global-search" id="global-search-form">${icon('search')}<input id="global-search" name="search" aria-label="Tìm công việc, nhấn Enter để xem kết quả" placeholder="Tìm kiếm công việc..."><kbd>↵</kbd></form><span class="toolbar-divider"></span>${themeButton()}<button class="icon-button notification-button" data-action="notifications" aria-label="Xem công việc cần chú ý">${icon('bell')}${getStats(state.tasks,today).dueToday?'<i></i>':''}</button>${avatar('an','top-avatar')}</div></header><main id="main" class="app-content" tabindex="-1">${content}</main><footer class="app-footer"><span><i class="dot green"></i> Dữ liệu lưu trên trình duyệt</span><span>Flow · Portfolio concept <span class="footer-separator">/</span> Tạo nhịp làm việc của riêng bạn.</span></footer></div></div>`;
}

function taskRow(t,today){return `<div class="task-row"><button class="task-check ${t.status==='done'?'checked':''}" data-complete="${esc(t.id)}" aria-label="${t.status==='done'?'Đánh dấu chưa hoàn thành':'Đánh dấu hoàn thành'}: ${esc(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):''}</button><div class="task-row-title"><button data-edit="${esc(t.id)}" class="task-title ${t.status==='done'?'completed':''}">${esc(t.title)}</button>${projectChip(t.project)}</div><div class="task-row-priority">${priority(t.priority)}</div><span class="due ${t.due&&t.due<today&&t.status!=='done'?'overdue':''}">${icon('calendar')}${dueLabel(t,today)}</span>${avatar(t.assignee,'small')}</div>`;}
export function overview(state,today,taskScope='today'){
 const stats=getStats(state.tasks,today);
 const scoped=state.tasks.filter(t=>taskScope==='all'?true:t.status!=='done'&&(taskScope==='upcoming'?t.due>today:t.due&&t.due<=today)).sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5);
 const completedWeek=state.tasks.filter(t=>t.status==='done'&&t.completedAt>=offsetDate(today,-6)&&t.completedAt<=today).length;
 const dayCounts=Array.from({length:7},(_,i)=>{const date=offsetDate(today,i-6);return {date,count:state.tasks.filter(t=>t.status==='done'&&t.completedAt===date).length};});
 const max=Math.max(2,...dayCounts.map(x=>x.count));
 return `<section class="page-header overview-header"><div><div class="eyebrow">MỖI NGÀY, TIẾN THÊM MỘT CHÚT</div><h1>Chào bạn, An <span class="greeting-sun">${icon('sun')}</span></h1><p>Bắt đầu một ngày có chủ đích. Bạn có <strong>${stats.dueToday} công việc</strong> đến hạn hôm nay.</p></div><div class="page-header-actions"><span class="date-chip">${icon('calendar')}${new Intl.DateTimeFormat('vi-VN',{day:'numeric',month:'long',year:'numeric'}).format(new Date(today+'T12:00:00'))}</span><button class="button" data-action="new-task">${icon('plus')}Thêm công việc</button></div></section>
 <div class="stats-grid">${[{name:'Tổng công việc',value:stats.total,icon:'folder',color:'violet',note:'Trong '+projects.length+' dự án',detail:'Cùng nhìn bức tranh lớn'}, {name:'Đang thực hiện',value:stats.doing,icon:'clock',color:'blue',note:'Từng bước tiến về phía trước',detail:'Giữ nhịp tập trung'}, {name:'Đã hoàn thành',value:stats.done,icon:'checkcircle',color:'green',note:stats.rate+'% tổng công việc',detail:'Mỗi bước nhỏ đều đáng giá'}, {name:'Cần chú ý',value:stats.overdue,icon:'flag',color:'orange',note:'Công việc đã quá hạn',detail:'Sắp xếp lại ưu tiên'}].map(s=>`<article class="stat-card"><div class="stat-top"><span>${s.name}</span><span class="stat-icon ${s.color}">${icon(s.icon)}</span></div><div class="stat-number">${s.value}<span class="stat-spark ${s.color}"><svg viewBox="0 0 90 30" aria-hidden="true"><path d="M1 25 12 21 22 23 32 13 42 17 52 8 62 12 75 4 89 6" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></span></div><div class="stat-caption"><span>${s.note}</span><span class="tooltip-info" title="${s.detail}">ⓘ</span></div></article>`).join('')}</div>
 <div class="overview-grid"><div class="overview-left"><section class="panel today-panel"><div class="panel-heading"><h2>Công việc của bạn <span class="count-pill">${scoped.length}</span></h2><a class="text-link" href="#/tasks">Xem tất cả ${icon('arrow')}</a></div><div class="scope-tabs" role="group" aria-label="Phạm vi công việc">${[['today','Hôm nay'],['upcoming','Sắp tới'],['all','Tất cả']].map(([id,label])=>`<button data-scope="${id}" class="${taskScope===id?'active':''}" aria-pressed="${taskScope===id}">${label}</button>`).join('')}</div><div class="dashboard-tasks">${scoped.length?scoped.map(t=>taskRow(t,today)).join(''):'<div class="calm-empty">'+icon('checkcircle')+'<h3>Bạn đã có một khoảng trống.</h3><p>Không có công việc trong mục này. Thử xem mục khác hoặc thêm việc mới.</p></div>'}</div><button class="inline-add" data-action="new-task">${icon('plus')}Thêm một công việc mới</button></section>
 <section class="projects-section"><div class="section-heading"><h2>Dự án đang chạy</h2><span class="subtle">${projects.length} dự án mẫu</span></div><div class="project-cards">${projects.map(p=>{const tasks=state.tasks.filter(t=>t.project===p.id);const s=getStats(tasks,today);return `<a href="#/board?project=${p.id}" class="project-card"><div class="project-card-top"><span class="project-square big ${p.color}">${icon(p.id==='p1'?'grid':p.id==='p2'?'spark':'bolt')}</span>${icon('arrowup','project-arrow')}</div><h3>${p.name}</h3><p>${p.description}</p><div class="project-progress-label"><span>${s.done}/${s.total} công việc</span><strong>${s.rate}%</strong></div><div class="progress-track"><span class="${p.color}" style="width:${s.rate}%"></span></div><div class="project-card-bottom">${avatarGroup()}<span>${icon('calendar')}${formatDate(offsetDate(today,p.dueOffset))}</span></div></a>`;}).join('')}</div></section></div>
 <div class="overview-right"><section class="panel productivity-panel"><div class="panel-heading"><h2>Nhịp làm việc</h2><span class="mini-label">7 ngày qua</span></div><div class="productivity-total"><strong>${completedWeek}</strong><span>công việc hoàn thành<br><small>Những bước nhỏ, tiến bộ thật.</small></span></div><div class="bar-chart" role="img" aria-label="${completedWeek} công việc hoàn thành trong 7 ngày qua"><div class="chart-grid"><span> ${max}</span><span> ${Math.ceil(max/2)}</span><span> 0</span></div><div class="chart-bars">${dayCounts.map((d,i)=>`<div class="bar-column"><div class="bar-well"><span class="bar ${i===6?'current':''}" style="height:${d.count?Math.max(8,d.count/max*100):3}%" title="${formatDate(d.date)}: ${d.count} công việc"></span></div><small>${new Intl.DateTimeFormat('vi-VN',{weekday:'short'}).format(new Date(d.date+'T12:00:00')).replace('Th ','T')}</small></div>`).join('')}</div></div><div class="chart-caption"><span class="chart-legend"></span>Hoàn thành theo ngày <span>Dữ liệu demo</span></div></section>
 <section class="panel progress-panel"><div class="panel-heading"><h2>Bức tranh tiến độ</h2>${icon('target')}</div><div class="donut-wrap"><div class="donut" style="--done:${stats.rate}%;--doing:${stats.total?stats.doing/stats.total*100:0}%;"><div><strong>${stats.rate}%</strong><span>hoàn thành</span></div></div></div><div class="progress-legend">${Object.entries(statuses).map(([id,name])=>`<div><span><i class="status-dot ${id}"></i>${name}</span><strong>${state.tasks.filter(t=>t.status===id).length}</strong></div>`).join('')}</div></section>
 <div class="focus-note">${icon('spark')}<div><strong>Nhịp của bạn. Cách của bạn.</strong><p>Ưu tiên một việc quan trọng, rồi bắt đầu từ đó.</p></div></div></div></div>`;
}

export function workHeader(route,filters,state){const p=projects.find(x=>x.id===filters.project);return `<section class="page-header work-header"><div><div class="eyebrow">TỪ Ý TƯỞNG ĐẾN HOÀN THÀNH</div><h1>${p?p.name:route==='board'?'Mọi việc, đúng nhịp.':'Tất cả công việc'}${p?`<span class="project-title-dot dot ${p.color}"></span>`:''}</h1><p>${p?p.description:'Một nơi cho những kế hoạch, ưu tiên và bước tiến của cả nhóm.'}</p></div><div class="page-header-actions">${avatarGroup()}<span class="member-caption">4 thành viên mẫu</span><button class="button" data-action="new-task">${icon('plus')}Thêm công việc</button></div></section><div class="view-toolbar"><div class="view-tabs"><a href="#/board${filters.project!=='all'?'?project='+filters.project:''}" class="${route==='board'?'active':''}">${icon('board')}Bảng Kanban</a><a href="#/tasks${filters.project!=='all'?'?project='+filters.project:''}" class="${route==='tasks'?'active':''}">${icon('list')}Danh sách</a></div><span class="auto-save">${icon('checkcircle')}Tự động lưu trên trình duyệt</span></div>`;}
export function filterBar(filters,route){return `<div class="filter-bar"><label class="filter-search">${icon('search')}<input id="task-search" type="search" placeholder="Tìm tên hoặc mô tả công việc…" aria-label="Tìm tên hoặc mô tả công việc" value="${esc(filters.search)}"></label><div class="filter-selects"><label class="sr-only" for="filter-project">Lọc theo dự án</label><select id="filter-project" data-filter="project"><option value="all">Mọi dự án</option>${projects.map(p=>`<option value="${p.id}" ${filters.project===p.id?'selected':''}>${p.name}</option>`).join('')}</select><label class="sr-only" for="filter-priority">Lọc theo ưu tiên</label><select id="filter-priority" data-filter="priority"><option value="all">Mọi ưu tiên</option>${Object.entries(priorities).map(([id,label])=>`<option value="${id}" ${filters.priority===id?'selected':''}>Ưu tiên ${label.toLowerCase()}</option>`).join('')}</select>${route==='tasks'?`<label class="sr-only" for="filter-status">Lọc theo trạng thái</label><select id="filter-status" data-filter="status"><option value="all">Mọi trạng thái</option>${Object.entries(statuses).map(([id,label])=>`<option value="${id}" ${filters.status===id?'selected':''}>${label}</option>`).join('')}</select>`:''}<label class="sr-only" for="filter-sort">Sắp xếp công việc</label><select id="filter-sort" data-filter="sort">${[['due','Theo hạn chót'],['priority','Theo ưu tiên'],['title','Theo tên A–Z']].map(([id,label])=>`<option value="${id}" ${filters.sort===id?'selected':''}>${label}</option>`).join('')}</select></div></div>`;}
function taskCard(t,today){return `<article class="kanban-card" draggable="true" data-drag="${esc(t.id)}" aria-label="${esc(t.title)}"><div class="card-tags">${(t.tags?.length?t.tags:['Công việc']).slice(0,2).map((tag,i)=>`<span class="tag ${i?'blue':'violet'}">${esc(tag)}</span>`).join('')}<button class="icon-button small-button" data-edit="${esc(t.id)}" aria-label="Chỉnh sửa ${esc(t.title)}">${icon('more')}</button></div><button class="card-title ${t.status==='done'?'completed':''}" data-edit="${esc(t.id)}">${esc(t.title)}</button><p class="card-description">${esc(t.description||'Thêm mô tả để làm rõ bước tiếp theo.')}</p><div class="card-project">${projectChip(t.project)}</div><div class="card-priority-row">${priority(t.priority)}<span class="due ${t.due&&t.due<today&&t.status!=='done'?'overdue':''}">${icon('calendar')}${dueLabel(t,today)}</span></div><div class="card-footer">${avatar(t.assignee,'small')}<label class="card-status-select"><span class="sr-only">Đổi trạng thái: ${esc(t.title)}</span><select data-move="${esc(t.id)}">${Object.entries(statuses).map(([id,name])=>`<option value="${id}" ${t.status===id?'selected':''}>${name}</option>`).join('')}</select>${icon('chevron')}</label></div></article>`;}
export function boardContent(tasks,today){return `<div class="kanban-board">${Object.entries(statuses).map(([status,label])=>{const list=tasks.filter(t=>t.status===status);return `<section class="kanban-column" data-column="${status}" aria-label="${label}"><div class="column-heading"><h2><i class="status-dot ${status}"></i>${label}<span class="column-count">${list.length}</span></h2><button class="icon-button small-button" data-new-status="${status}" aria-label="Thêm công việc vào ${label}">${icon('plus')}</button></div><div class="column-content">${list.map(t=>taskCard(t,today)).join('')}${!list.length?'<div class="column-empty">Một khoảng trống cho bước tiếp theo.</div>':''}</div><button class="column-add" data-new-status="${status}">${icon('plus')}Thêm công việc</button></section>`;}).join('')}</div>`;}
export function listContent(tasks,today){if(!tasks.length)return emptyState();return `<div class="task-table-wrap"><table class="task-table"><thead><tr><th scope="col" class="task-name-col">Tên công việc</th><th scope="col">Trạng thái</th><th scope="col">Ưu tiên</th><th scope="col">Hạn chót</th><th scope="col">Phụ trách</th><th scope="col"><span class="sr-only">Chỉnh sửa</span></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><div class="table-task-name"><button class="task-check ${t.status==='done'?'checked':''}" data-complete="${esc(t.id)}" aria-label="Đổi trạng thái hoàn thành: ${esc(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):''}</button><div><button class="task-title ${t.status==='done'?'completed':''}" data-edit="${esc(t.id)}">${esc(t.title)}</button>${projectChip(t.project)}</div></div></td><td><label class="status-select ${t.status}"><span class="sr-only">Trạng thái ${esc(t.title)}</span><i class="status-dot ${t.status}"></i><select data-move="${esc(t.id)}">${Object.entries(statuses).map(([id,name])=>`<option value="${id}" ${t.status===id?'selected':''}>${name}</option>`).join('')}</select></label></td><td>${priority(t.priority)}</td><td><span class="due ${t.due&&t.due<today&&t.status!=='done'?'overdue':''}">${icon('calendar')}${dueLabel(t,today)}</span></td><td>${avatar(t.assignee,'small')}</td><td><button class="icon-button small-button" data-edit="${esc(t.id)}" aria-label="Chỉnh sửa ${esc(t.title)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table></div>`;}
export function workPage(route,state,today,filters){const tasks=filterTasks(state.tasks,filters);return `${workHeader(route,filters,state)}${filterBar(filters,route)}<div class="result-meta"><span id="result-count" role="status">${tasks.length} công việc</span><span class="subtle">${route==='board'?'Kéo thả thẻ hoặc dùng menu trạng thái để di chuyển.':'Chọn tên công việc để xem và chỉnh sửa.'}</span></div><div id="work-results">${route==='board'?boardContent(tasks,today):listContent(tasks,today)}</div>`;}

export function taskDialog(task,isNew=false){return `<form id="task-form" novalidate><div class="dialog-top"><span class="eyebrow">${isNew?'MỘT BƯỚC TIẾN MỚI':'CHI TIẾT CÔNG VIỆC'}</span><button type="button" class="icon-button" data-action="close-dialog" aria-label="Đóng chi tiết">${icon('close')}</button></div><h2 id="task-dialog-title">${isNew?'Thêm công việc':'Chỉnh sửa công việc'}</h2><p class="dialog-description">Một mục tiêu rõ ràng là khởi đầu của một việc hoàn thành.</p><div class="form-field"><label for="task-title">Tên công việc <span>*</span></label><input id="task-title" name="title" value="${esc(task.title)}" placeholder="Bạn muốn hoàn thành điều gì?" maxlength="120" required aria-describedby="error-title"><span class="field-error" id="error-title"></span></div><div class="form-field"><label for="task-description">Mô tả</label><textarea id="task-description" name="description" rows="4" maxlength="3000" placeholder="Thêm ngữ cảnh, kết quả mong muốn hoặc bước tiếp theo…">${esc(task.description)}</textarea></div><div class="form-grid">${[['project','Dự án',projects.map(p=>[p.id,p.name])],['assignee','Người phụ trách',members.map(m=>[m.id,m.name])],['status','Trạng thái',Object.entries(statuses)],['priority','Ưu tiên',Object.entries(priorities)]].map(([key,label,options])=>`<div class="form-field"><label for="task-${key}">${label}</label><select id="task-${key}" name="${key}" aria-describedby="error-${key}">${options.map(([value,text])=>`<option value="${value}" ${task[key]===value?'selected':''}>${text}</option>`).join('')}</select><span class="field-error" id="error-${key}"></span></div>`).join('')}</div><div class="form-field"><label for="task-due">Hạn chót <small>Không bắt buộc</small></label><input id="task-due" name="due" type="date" value="${esc(task.due)}" aria-describedby="error-due"><span class="field-error" id="error-due"></span></div><div class="dialog-demo-note">${icon('checkcircle')}Chỉ lưu trên trình duyệt này. Không gửi thông báo đến thành viên.</div><div class="dialog-footer">${!isNew?`<button type="button" class="button danger-ghost" data-delete="${esc(task.id)}">${icon('trash')}Xóa</button>`:'<span></span>'}<div><button type="button" class="button secondary" data-action="close-dialog">Hủy</button><button type="submit" class="button">${icon('check')}Lưu công việc</button></div></div></form>`;}

export function landing(state,today){return `<div class="landing"><header class="landing-header landing-wrap"><a class="brand" href="#/" aria-label="Flow — Trang chủ">${logo()}</a><nav aria-label="Điều hướng giới thiệu"><a href="#features" data-scroll="features">Tính năng</a><a href="#workflow" data-scroll="workflow">Cách hoạt động</a><a href="#/app">Khám phá workspace</a></nav><div class="landing-header-actions">${themeButton()}<a class="button small" href="#/app">Mở bản demo ${icon('arrowup')}</a></div></header><main id="main" tabindex="-1"><section class="landing-hero landing-wrap"><span class="launch-pill"><i></i>Không gian gọn gàng. Tâm trí rộng mở. ${icon('arrow')}</span><h1>Ít rối hơn.<br><span>Nhiều <i>flow</i> hơn.</span></h1><p>Từ những ý tưởng đầu tiên đến dấu tick cuối cùng.<br>Một nơi để bạn và công việc tìm thấy nhịp chung.</p><div class="hero-actions"><a href="#/app" class="button large">Bắt đầu trải nghiệm ${icon('arrow')}</a><a href="#/board" class="button secondary large">${icon('board')}Xem bảng công việc</a></div><div class="hero-benefits"><span>${icon('checkcircle')}Không cần đăng ký</span><span>${icon('checkcircle')}Sáng / tối theo ý bạn</span><span>${icon('checkcircle')}Dữ liệu lưu tại máy</span></div></section><section class="landing-preview landing-wrap" aria-label="Xem trước sản phẩm Flow"><div class="preview-browser-bar"><div class="browser-dots"><i></i><i></i><i></i></div><span>${icon('link')}flow.workspace / tổng quan</span><span class="preview-live">${icon('bolt')}Bản demo tương tác</span></div><div class="product-preview"><div class="preview-sidebar"><a class="brand" href="#/app">${logo()}</a><div class="preview-workspace">S <span>Studio Workspace</span></div><a href="#/app" class="preview-nav active">${icon('grid')}Tổng quan</a><a href="#/board" class="preview-nav">${icon('board')}Bảng công việc</a><a href="#/tasks" class="preview-nav">${icon('list')}Tất cả công việc</a><span class="preview-side-label">DỰ ÁN CỦA BẠN</span>${projects.map(p=>`<a href="#/board?project=${p.id}" class="preview-nav"><i class="dot ${p.color}"></i>${p.name}</a>`).join('')}<div class="preview-profile">${avatar('an','small')}<span>Minh An<small>Freelancer</small></span></div></div><div class="preview-content"><div class="preview-content-top"><span>Không gian làm việc <span>/</span> <strong>Tổng quan</strong></span><div>${icon('search')}${icon('bell')}${avatar('an','small')}</div></div><div class="preview-greeting"><div><span class="eyebrow">MỖI NGÀY, TIẾN THÊM MỘT CHÚT</span><h2>Chào bạn, An ${icon('sun')}</h2><p>Một ngày mới, những bước tiến mới.</p></div><a class="button small" href="#/app">${icon('plus')}Thêm công việc</a></div><div class="preview-stat-grid">${[['Tổng công việc',state.tasks.length,'folder','violet'],['Đang thực hiện',getStats(state.tasks).doing,'clock','blue'],['Đã hoàn thành',getStats(state.tasks).done,'checkcircle','green']].map(([name,value,i,c])=>`<div><span>${name}<b class="${c}">${icon(i)}</b></span><strong>${value}</strong><small>${name==='Đã hoàn thành'?'Mỗi bước nhỏ đều đáng giá':'Cùng giữ một nhịp làm việc tốt'}</small></div>`).join('')}</div><div class="preview-bottom-grid"><section class="preview-task-panel"><h3>Công việc của bạn <a href="#/tasks">Xem tất cả ↗</a></h3><div class="preview-tabs"><span>Hôm nay</span><span>Sắp tới</span><span>Tất cả</span></div>${state.tasks.filter(t=>t.status!=='done').slice(0,3).map(t=>`<a href="#/tasks" class="preview-task"><span class="mini-check"></span><span>${esc(t.title)}<small>${projects.find(p=>p.id===t.project)?.name}</small></span>${avatar(t.assignee,'small')}</a>`).join('')}</section><section class="preview-progress"><h3>Bức tranh tiến độ</h3><div class="donut" style="--done:${getStats(state.tasks).rate}%;--doing:${state.tasks.length?getStats(state.tasks).doing/state.tasks.length*100:0}%"><div><strong>${getStats(state.tasks).rate}%</strong><span>hoàn thành</span></div></div><span><i class="status-dot done"></i>Đang từng bước tiến về đích</span></section></div></div></div><div class="preview-caption"><span>Những dự án, thành viên và công việc trên là dữ liệu minh họa.</span><a href="#/app">Thử trực tiếp ${icon('arrowup')}</a></div></section><section class="features-section landing-wrap" id="features"><div class="landing-section-heading"><span class="eyebrow">VỪA ĐỦ ĐỂ LÀM VIỆC TỐT HƠN</span><h2>Mọi việc có chỗ.<br>Tâm trí có khoảng trống.</h2><p>Không thêm phức tạp vào một ngày vốn đã bận rộn.</p></div><div class="feature-grid">${[['board','violet','Thấy rõ bước tiếp theo','Kéo thả công việc qua từng giai đoạn. Một cái nhìn để biết mọi thứ đang ở đâu.'],['target','blue','Giữ đúng điều ưu tiên','Lọc theo dự án, trạng thái và mức độ quan trọng. Tập trung vào việc cần làm.'],['moon','orange','Một không gian, hai sắc thái','Sáng cho ngày mới. Tối cho lúc cần tập trung. Chuyển đổi chỉ bằng một nút bấm.']].map(([i,c,title,text])=>`<article><span class="feature-icon ${c}">${icon(i)}</span><h3>${title}</h3><p>${text}</p></article>`).join('')}</div></section><section class="workflow-section" id="workflow"><div class="landing-wrap"><div class="landing-section-heading"><span class="eyebrow">THẬT ĐƠN GIẢN ĐỂ BẮT ĐẦU</span><h2>Từ “cần làm” đến <span>“đã xong”.</span></h2></div><div class="workflow-steps">${[['01','Ghi lại điều cần làm','Tạo công việc, chọn người phụ trách và đặt một hạn chót rõ ràng.'],['02','Tìm nhịp của riêng bạn','Sắp xếp ưu tiên, chuyển đổi giữa Kanban và danh sách theo cách bạn thích.'],['03','Nhìn thấy mình tiến bộ','Đánh dấu hoàn thành và theo dõi tiến độ cập nhật ngay trên dashboard.']].map(([n,title,desc])=>`<article><span>${n}</span><h3>${title}</h3><p>${desc}</p></article>`).join('')}</div></div></section><section class="landing-cta landing-wrap"><span class="eyebrow">MỘT VIỆC NHỎ. MỘT KHỞI ĐẦU MỚI.</span><h2>Công việc vẫn ở đó.<br><span>Bắt đầu với một chút flow.</span></h2><a href="#/app" class="button large">Khám phá workspace ${icon('arrow')}</a><p>Portfolio concept · Không cần tài khoản · Không thu phí</p></section></main><footer class="landing-footer landing-wrap"><a class="brand" href="#/">${logo()}</a><span>© 2026 Flow. Dự án concept tự thực hiện.</span><span>Được tạo cho những ngày làm việc có nhịp.</span></footer></div>`;}
